import { createHash } from "node:crypto";
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

// The token copy is generated by design-system/scripts/sync-tokens.mjs. This app never imports
// from design-system/; the test only reads it when the whole repository is checked out.
const appRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../../..");
const copyPath = path.join(appRoot, "src/styles/tanaw-tokens.css");
const sourcePath = path.resolve(appRoot, "../design-system/tokens/tanaw.css");
const HEADER_END = "\n */\n";

const normalize = (text: string) => text.replace(/\r\n/g, "\n");
const sha256 = (text: string) => createHash("sha256").update(normalize(text), "utf8").digest("hex");

function readCopy() {
  const text = normalize(readFileSync(copyPath, "utf8"));
  const recorded = /Source SHA-256: ([0-9a-f]{64})/.exec(text)?.[1];
  const end = text.indexOf(HEADER_END);
  return { recorded, body: end < 0 ? "" : text.slice(end + HEADER_END.length) };
}

describe("design tokens", () => {
  it("are a generated copy that has not been edited by hand", () => {
    const { recorded, body } = readCopy();
    expect(recorded, "the copy is missing its generated header").toBeDefined();
    expect(sha256(body), "src/styles/tanaw-tokens.css was edited; change design-system/tokens/tanaw.css and run node design-system/scripts/sync-tokens.mjs").toBe(recorded);
  });

  it.skipIf(!existsSync(sourcePath))("match the design system's token file", () => {
    expect(readCopy().recorded, "the token copy is stale; run node design-system/scripts/sync-tokens.mjs").toBe(sha256(readFileSync(sourcePath, "utf8")));
  });
});
